require __DIR__.'/config.php';if(current_user())go('dashboard.php');$error='';$identity='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$identity=trim((string)($_POST['identity']??''));$password=(string)($_POST['password']??'');if($identity===''||$password==='')$error='Enter your email or phone and password.';else{try{$s=db()->prepare("SELECT u.user_id,u.password_hash,u.status,u.failed_login_attempts,c.customer_id,c.full_name FROM users u JOIN customers c ON c.customer_id=u.linked_customer_id JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE (LOWER(c.email)=LOWER(?) OR c.phone=?) AND r.role_name='Customer' LIMIT 1");$s->execute([$identity,$identity]);$u=$s->fetch();if(!$u||$u['status']!=='active'||!password_verify($password,$u['password_hash'])){if($u&&$u['status']==='active'){$n=(int)$u['failed_login_attempts']+1;$status=$n>=5?'locked':'active';db()->prepare('UPDATE users SET failed_login_attempts=?,status=? WHERE user_id=?')->execute([$n,$status,$u['user_id']]);try{audit((int)$u['user_id'],'LOGIN','users',(int)$u['user_id'],'Failed customer login','failure');}catch(Throwable $ignore){}}$error='We could not sign you in with those details. Check them or contact your branch.';}else{session_regenerate_id(true);$_SESSION['auth']=['id'=>(int)$u['user_id'],'customer_id'=>(int)$u['customer_id'],'role'=>'Customer','name'=>$u['full_name']];db()->prepare('UPDATE users SET failed_login_attempts=0,last_login_at=NOW() WHERE user_id=?')->execute([$u['user_id']]);try{audit((int)$u['user_id'],'LOGIN','users',(int)$u['user_id'],'Customer logged in');}catch(Throwable $ignore){}flash('Welcome back, '.$u['full_name'].'.');go('dashboard.php');}}catch(Throwable $x){$error='Sign in is temporarily unavailable. Please try again later.';}}}
render_start('Sign in');?><section class="login-shell"><div class="login-aside"><div class="eyebrow">Your banking, all in one place</div><h1>Welcome back.</h1><p>Sign in to see your accounts and stay close to what matters.</p><div class="monogram">B</div></div><div class="login-form"><div class="eyebrow dark">Secure customer sign in</div><h2>Sign in to BankEase</h2><p class="muted">Use the email or phone number linked to your customer profile.</p><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?><form method="post" autocomplete="on"><?=csrf()?><div class="field"><label for="identity">Email or phone</label><input id="identity" name="identity" value="<?=e($identity)?>" autocomplete="username" required></div><div class="field"><label for="password">Password</label><div class="password"><input id="password" name="password" type="password" autocomplete="current-password" required><button type="button" data-password-toggle="password" aria-pressed="false">Show</button></div></div><button class="button navy full" type="submit">Sign in securely</button></form><p class="form-switch">New to BankEase? <a href="<?=e(url('register.php'))?>">Open an account</a></p></div></section><?php render_end();?>
